import tempfile, os
from typing import Annotated, TypedDict
from langgraph.checkpoint.sqlite import SqliteSaver
from langgraph.graph import END, START, StateGraph
from langgraph.types import Command, interrupt

def merge(l, r): return {**(l or {}), **(r or {})}
class S(TypedDict, total=False):
    run_id: str
    lanes: Annotated[dict, merge]
    snapshots: dict
    packets: Annotated[dict, merge]
    bundle: str

FAIL = {"verify_b": True, "candidate": False}
def build(saver):
    g = StateGraph(S)
    g.add_node("launch_a", lambda s: {"lanes": {"a": 1}})
    g.add_node("launch_b", lambda s: {"lanes": {"b": 1}})
    def handoff(s):
        d = interrupt({"kind": "worker_handoff"})
        return {"snapshots": {"a": "A0", "b": "B0"}}
    g.add_node("handoff", handoff)
    def verifier(n):
        def f(s):
            if FAIL.get(f"verify_{n}"): raise RuntimeError(f"{n} blocked")
            return {"packets": {n: s["snapshots"][n]}}
        return f
    g.add_node("verify_a", verifier("a")); g.add_node("verify_b", verifier("b"))
    def cand(s):
        if FAIL["candidate"]: raise RuntimeError("cand blocked")
        return {"bundle": str(s["packets"])}
    g.add_node("candidate", cand)
    for n in ("launch_a", "launch_b"): g.add_edge(START, n)
    g.add_edge(["launch_a", "launch_b"], "handoff")
    g.add_edge("handoff", "verify_a"); g.add_edge("handoff", "verify_b")
    g.add_edge(["verify_a", "verify_b"], "candidate"); g.add_edge("candidate", END)
    return g.compile(checkpointer=saver)

def show(label, st):
    print(label, "next=", st.next, "tasks=", [(t.name, bool(t.error)) for t in st.tasks], "vals=", {k: v for k, v in st.values.items() if k in ("snapshots", "packets")}, "src=", st.metadata.get("source") if st.metadata else None)

d = tempfile.mkdtemp()
cfg = {"configurable": {"thread_id": "t"}}
with SqliteSaver.from_conn_string(os.path.join(d, "db")) as saver:
    g = build(saver)
    g.invoke({"run_id": "t"}, cfg)
    try: g.invoke(Command(resume={"freeze": True}), cfg)
    except RuntimeError as e: print("err", e)
    show("HEAD(state B)", g.get_state(cfg))
    for h in g.get_state_history(cfg):
        show("  hist", h)
    fan = {"verify_a", "verify_b"}
    fork = next(h for h in g.get_state_history(cfg) if {t.name for t in h.tasks} == fan)
    print("fork by tasks:", fork.config["configurable"]["checkpoint_id"], "head:", g.get_state(cfg).config["configurable"]["checkpoint_id"])
    new = g.update_state(fork.config, {"snapshots": {"a": "A0", "b": "B1"}}, as_node="handoff")
    head = g.get_state(cfg)
    show("AFTER FORK", head)
    print("parent == fork:", head.parent_config["configurable"]["checkpoint_id"] == fork.config["configurable"]["checkpoint_id"])
    FAIL["verify_b"] = False; FAIL["candidate"] = True
    try: g.invoke(None, cfg)
    except RuntimeError as e: print("err", e)
    show("HEAD(state A)", g.get_state(cfg))
    for h in g.get_state_history(cfg):
        show("  hist", h)
    fork2 = next(h for h in g.get_state_history(cfg) if {t.name for t in h.tasks} == fan and set(h.next) == fan)
    print("fork2 is first fork:", fork2.config["configurable"]["checkpoint_id"] == head.config["configurable"]["checkpoint_id"] or fork2.config["configurable"]["checkpoint_id"])
    g.update_state(fork2.config, {"snapshots": {"a": "A1", "b": "B1"}}, as_node="handoff")
    show("AFTER FORK2", g.get_state(cfg))
    FAIL["candidate"] = False
    print(g.invoke(None, cfg))
EOF
